import{_ as n,o as t,c as i,a2 as r}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Glossar der Begriffe","description":"","frontmatter":{},"headers":[],"relativePath":"de/90-术语词典.md","filePath":"de/90-术语词典.md"}'),s={name:"de/90-术语词典.md"};function d(a,e,u,l,h,o){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="glossar-der-begriffe" tabindex="-1">Glossar der Begriffe <a class="header-anchor" href="#glossar-der-begriffe" aria-label="Permalink to &quot;Glossar der Begriffe&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Punkt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>90</td></tr><tr><td>Modul</td><td>Anhänge und Referenzmaterialien</td></tr><tr><td>Kernschlüsselwörter</td><td>Begriffsglossar, Kernkonzepte, Definitionen, vereinheitlichte Terminologie, Hengyuanzhou</td></tr></tbody></table><h2 id="_1-erklarung-der-begriffe" tabindex="-1">1. Erklärung der Begriffe <a class="header-anchor" href="#_1-erklarung-der-begriffe" aria-label="Permalink to &quot;1. Erklärung der Begriffe&quot;">​</a></h2><p>Dieses Glossar enthält die Kernbegriffe des Einstellungssystems der Anker-Symbiose-Zivilisation, mit dem Ziel, die Verwendung der Terminologie in allen Dokumenten zu vereinheitlichen und die Konsistenz und Genauigkeit der Konzeptausdrücke zu gewährleisten. Alle Begriffe sind nach dem ersten Buchstaben des chinesischen Pinyin geordnet, und jeder Begriff enthält den Begriffnamen, den englischen Referenznamen (falls vorhanden), die Definition und eine kurze Erklärung. Dieses Glossar ist ein dynamisch aktualisiertes Dokument, und neue Begriffe werden kontinuierlich hinzugefügt, wenn sich das Einstellungssystem erweitert.</p><h2 id="_2-tabelle-der-kernbegriffe" tabindex="-1">2. Tabelle der Kernbegriffe <a class="header-anchor" href="#_2-tabelle-der-kernbegriffe" aria-label="Permalink to &quot;2. Tabelle der Kernbegriffe&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nr.</th><th>Begriff</th><th>Definition und Erklärung</th></tr></thead><tbody><tr><td>1</td><td>Anker</td><td>Ein stabiler Knoten im Rechtsnetzwerk, der Koordinatenmaßstab für die Aufrechterhaltung der Stabilität der Dimensionsgesetze, die Umsetzung interdimensionaler Verbindungen und die Zeitrückholung. Der Anker ist im Wesentlichen ein hochdichtes Kondensat der grundlegenden Gesetze des Universums an einer bestimmten räumlichen Position, mit Selbst erhaltungs- und Kalibrierungsfähigkeit.</td></tr><tr><td>2</td><td>Anker-Symbiose-Zivilisation</td><td>Eine Zivilisationsform, die den Ankermechanismus als technische Grundlage und die symbiotische Evolution als Kernkonzept hat. Sie wendet sich gegen das räuberische Kultivierungssystem und befürwortet die Rückgabe des Rechts auf Wahl des Schicksals und der Evolution an alle Wesen, wodurch mehr Arbeit mehr Gewinn, Selbsterzeugung und Selbstwachstum, jeder hat einen Weg, alle Rassen schreiten gemeinsam voran verwirklicht werden.</td></tr><tr><td>3</td><td>Hengyuanzhou</td><td>Abkürzung für &quot;Wanling Hengmao Benyuan Zhou&quot;, das gesamte Universum, in dem die Anker-Symbiose-Zivilisation lebt und regiert. Es ist ein zusammengesetztes Wesen, das aus vier Schichten besteht: materielle Dimension, Energieschicht, Bewusstseinsdomäne und Rechtsnetzwerk.</td></tr><tr><td>4</td><td>Wanling Hengmao Benyuan Zhou</td><td>Der vollständige Name von Hengyuanzhou. &quot;Wanling&quot; bezieht sich auf alle Lebensformen mit Wahrnehmungs- und Evolutionspotenzial, &quot;Hengmao&quot; bezieht sich auf den Ankermechanismus, der das kosmische Gleichgewicht aufrechterhält, &quot;Benyuan Zhou&quot; betont das Wesensmerkmal, die grundlegenden Gesetze als Grundlage und die symbiotische Evolution als Richtung zu haben.</td></tr><tr><td>5</td><td>Symbiose</td><td>Eines der Kernkonzepte der Anker-Symbiose-Zivilisation, bezieht sich auf die gemeinsame Evolution, die durch gegenseitig vorteilhafte Zusammenarbeit zwischen verschiedenen lebenden Individuen, Rassen und Zivilisationen erreicht wird, anstatt eine räuberische Evolution auf Kosten anderer.</td></tr><tr><td>6</td><td>Räuberisches Kultivierungssystem</td><td>Eine Kultivierungsmethode, die die eigene Evolution durch das Verschlingen der Energie, des Glücks und sogar der Herkunft der Schwachen verwirklicht. Ein Systemtyp, dem die Anker-Symbiose-Zivilisation entschieden widerspricht, und der als Wurzel der beschleunigten Zunahme der kosmischen Entropie und der häufigen Zivilisationsbrüche angesehen wird.</td></tr><tr><td>7</td><td>Dreihundert Sätze des Ursprungs-Kultivierungssystems</td><td>Orthodoxe Kultivierungswege, die direkt aus den grundlegenden Gesetzen des Universums extrahiert und durch Anker verifiziert wurden, insgesamt dreihundert Sätze, unterteilt in sechs Kategorien: Ursprungsableitung, Lebenszyklus, Raumrecht, Bewusstseinserhöhung, Symbiosenetzwerk und angewandte Technik, fünfzig Sätze pro Kategorie.</td></tr><tr><td>8</td><td>Drei Ursprungsgrundlagen</td><td>Die ersten drei grundlegenden Sätze unter den dreihundert Sätzen — Ableitungs-Iterations-System (1. Satz), Lebenszyklus-System (2. Satz), Raumrecht-Steuerungssystem (3. Satz), die die Kultivierungsgrundlage für alle anderen Systeme sind.</td></tr><tr><td>9</td><td>Ableitungs-Iterations-System</td><td>Der 1. Satz des Ursprungs-Kultivierungssystems, mit dem Kernmerkmal der hundertfachen Erhöhung der Kultivierungsableitung, nutzt die technische Anwendung der Multiplikationsfrucht, um die Ableitungsfähigkeit um das Hundertfache zu erhöhen, und betont die Optimierung des Kultivierungswegs durch Ableitung, Verifizierung und Iteration.</td></tr><tr><td>10</td><td>Lebenszyklus-System</td><td>Der 2. Satz des Ursprungs-Kultivierungssystems, mit dem guten Kreislauf der Lebensenergie als Kern, betont, dass der Energieaustausch zwischen dem Kultivierenden selbst und der Umgebung zyklisch und nicht räuberisch sein muss.</td></tr><tr><td>11</td><td>Raumrecht-Steuerungssystem</td><td>Der 3. Satz des Ursprungs-Kultivierungssystems, mit dem Verständnis und der Steuerung der Raumgesetze als Kern, ist die Kultivierungsgrundlage für wichtige Anwendungen wie interdimensionale Interaktion, Konstruktion isolierter Räume und Spiegelkopiertechnologie.</td></tr><tr><td>12</td><td>Multiplikationsfrucht</td><td>Die Multiplikationsfrucht, die aus der Welt von One Piece stammt, wird in Hengyuanzhou technisch angewendet und kann die Ableitungsfähigkeit des Kultivierenden um das Hundertfache erhöhen. Sie ist das zentrale Hilfsmittel des Ableitungs-Iterations-Systems. Einer der Anfangs-Buffs.</td></tr><tr><td>13</td><td>Gemeinsamer Produktionsvertrag-Mechanismus</td><td>Der Ressourcenallokationsmechanismus der Anker-Symbiose-Zivilisation, der die kosmischen Kultivierungsressourcen durch &quot;Vertrag&quot; an Individuen oder Gruppen verteilt, und die Vertragspartner erhalten das Nutzungsrecht an den Ressourcen durch Arbeit und Beitrag, wodurch mehr Arbeit mehr Gewinn verwirklicht wird.</td></tr><tr><td>14</td><td>20%-Aktivierungsstrategie</td><td>Das phasenweise strategische Ziel der Anker-Symbiose-Zivilisation, in der Anfangsphase 20% aller Wesen des Universums zu den höchsten dimensionalen Starken zu aktivieren, und diese als Rückgrat zu nutzen, um die gemeinsame Evolution der verbleibenden 80% der Wesen voranzutreiben.</td></tr><tr><td>15</td><td>Höchster dimensionaler Starker</td><td>Ein Starker, der ein extrem hohes Kultivierungsreich erreicht hat und in der Lage ist, die Stabilität der Gesetze einer Dimension allein aufrechtzuerhalten. Er ist das Zielausbildungsobjekt der 20%-Aktivierungsstrategie und auch eine wichtige Erhaltungskraft des Ankernetzwerks.</td></tr><tr><td>16</td><td>Rechtsnetzwerk</td><td>Die vierte Schicht der Struktur von Hengyuanzhou, die unterliegende Betriebsschicht der grundlegenden Gesetze des Universums und die Grundschicht der Anker. Das Rechtsnetzwerk durchdringt das gesamte Universum und ist die technische Grundlage aller Rechtsoperationen (einschließlich Raumsteuerung, Zeitrückholung und Energieumwandlung).</td></tr><tr><td>17</td><td>Dimension</td><td>Ein Existenzbereich, der durch eine Reihe relativ stabiler Gesetze definiert ist und eine unabhängige raum-zeitliche Kontinuität aufweist. Jede Dimension hat einzigartige physikalische Konstanten, Energiedichte, Zeitflussgeschwindigkeit und Bewusstseinsaktivität.</td></tr><tr><td>18</td><td>Rechtsbarriere</td><td>Eine Rechtsschranke, die benachbarte Dimensionen trennt, deren Stärke vom Grad der Unterschiede der Rechtsparameter zwischen benachbarten Dimensionen abhängt. Die Dimensionstraversierung erfordert die Überwindung der Rechtsbarriere.</td></tr><tr><td>19</td><td>Rechtsfingerabdruck</td><td>Eine eindeutige Kennung, die durch Hash-Operation der zentralen Rechtsparameter jeder Dimension erzeugt wird, mit einer Länge von 128 Bit, und ist einer der zentralen Parameter des dimensionskoordinatensystems.</td></tr><tr><td>20</td><td>Zuerst beobachten, dann begrenzt eingreifen</td><td>Das wichtigste Betriebsprinzip der Zeitrückholung und der interdimensionalen Archäologie, das verlangt, dass jede Rückholung oder Archäologie zuerst die reine Beobachtungsphase abschließen muss, und erst nach Bestätigung, dass keine signifikanten Risiken bestehen, eine begrenzte Intervention durchgeführt werden kann.</td></tr><tr><td>21</td><td>Spiegelkopie</td><td>Ein hochpräzises Kopiergerät auf Basis der Raumgesetze, das in der Lage ist, eine vollständige 1:1-Kopie des Zielbereichs durchzuführen, ohne das Originalobjekt zu berühren, und ist die zentrale Ausrüstung des Fernarchäologie-Schemas.</td></tr><tr><td>22</td><td>Isolierter Raum</td><td>Ein unabhängiger Rechtsbereich, der durch Raumrecht-Steuerungstechnologie konstruiert wurde, wird verwendet, um archäologische Kopien zu tragen und als Arbeitsplatz für Archäologen zu dienen, und ist vollständig durch eine Rechtsbarriere vom äußeren Universum getrennt.</td></tr><tr><td>23</td><td>Nur Wissen zurücksenden</td><td>Das zentrale Prinzip des Archäologieprotokolls, bezieht sich darauf, dass das, was während der Archäologie vom Zielobjekt erhalten wird, nur abstraktes Wissen und Informationen sein darf, und keine Materie, Energie oder Lebewesen zurückgesendet werden darf.</td></tr><tr><td>24</td><td>Informationsreinigung</td><td>Der technische Prozess, die in den Originalinformationen getragenen Rechtsspuren der Herkunftsdimension vollständig zu entfernen und nur den reinen semantischen Inhalt zu behalten, ist ein Schlüsselglied zur Gewährleistung der Sicherheit des zurückgesendeten Wissens.</td></tr><tr><td>25</td><td>Zeitparadox</td><td>Das Phänomen des Selbstwiderspruchs in der Kausallogik, der durch Interventionsverhalten während Zeitrückholungsoperationen verursacht wird, einschließlich vier Hauptkategorien: Großvater-Paradox, Informationsparadox, Ontologie-Paradox und Ereignisparadox.</td></tr><tr><td>26</td><td>Kausalkette</td><td>Die kontinuierliche lineare Struktur von Ursache und Wirkung zwischen Ereignissen, ist das Kernkonzept der Zeitgesetze. Das zentrale Risiko von Zeitrückholungsoperationen ist die Störung der Kausalkette.</td></tr><tr><td>27</td><td>Symbiose-Verfassung</td><td>Das Grundgesetz der Anker-Symbiose-Zivilisation, mit der höchsten Rechtskraft, etabliert die zivilisatorische Grundlage der Anti-Räuberei und Pro-Symbiose sowie die sieben grundlegenden Verfassungsprinzipien.</td></tr><tr><td>28</td><td>Gleichheit aller Rassen</td><td>Eines der sieben grundlegenden Prinzipien der Symbiose-Verfassung, bezieht sich darauf, dass alle Lebensformen unabhängig von Rasse, Kultivierungsniveau oder Herkunft vor dem Gesetz gleich sind.</td></tr><tr><td>29</td><td>Seltsames Leben</td><td>Eine Lebensform, die nicht der konventionellen Lebensdefinition entspricht und eine besondere Existenzform aufweist, muss nach drei Arten standardisierter Behandlungsverfahren identifiziert und verwaltet werden.</td></tr><tr><td>30</td><td>Seltsame Energie</td><td>Eine Energieform, die nicht der konventionellen Energieklassifizierung entspricht und besondere Attribute und Verhaltensmuster aufweist, muss nach drei Arten standardisierter Behandlungsverfahren klassifiziert und kontrolliert werden.</td></tr><tr><td>31</td><td>Dunkler Ersatzkörper</td><td>Eine besondere Lebensform, die ethische Fragen der Koexistenz zweier Seelen betrifft, muss nach den ethischen Richtlinien für zwei Seelen und vier Arten von Zweigbehandlungsregeln verwaltet werden.</td></tr><tr><td>32</td><td>Ethik zweier Seelen</td><td>Ethische Richtlinien für den Zustand der Koexistenz zweier Seelen im Dunklen Ersatzkörper, der Kern ist die Achtung der jeweiligen Rechte der beiden Seelen, und die erzwungene Fusion oder die Beseitigung einer der beiden Parteien ist verboten.</td></tr><tr><td>33</td><td>Fünf Arten der Klassifizierung der Symbiose-Zivilisation</td><td>Fünf Arten von symbiotischen Gesellschaftstypen, die auf den Merkmalen der Zivilisationen der realen Welt basieren: intensiver Typ Ostasiens, Wohlfahrtstyp Nordeuropas, pluralistischer Typ Nordamerikas, sozialer Typ Kontinentaleuropas, aufholender Entwicklungstyp.</td></tr><tr><td>34</td><td>Vier-Phasen-Erhöhungsweg</td><td>Die Vier-Phasen-Route für die allgemeine Erhöhung des Universums Hengyuanzhou: Realitätsgrundlage → Technologieermächtigung → Bewusstseinsevolution → interstellare Symbiose.</td></tr><tr><td>35</td><td>Realität als Grundlage</td><td>Eine der grundlegenden Positionen der Anker-Symbiose-Zivilisation, bezieht sich darauf, dass die reale Welt die einzige reale Welt ist, die Romanwelt ein falsches Gedankenexperiment ist, das unzureichende Fiktive wird durch die Realität ergänzt, und das, was in der Realität nicht existiert, wird durch Aufwertung auf Basis der Gesetze geschaffen.</td></tr><tr><td>36</td><td>Symbiosegrad</td><td>Ein quantitativer Indikator zur Bewertung des Integrationsgrades einer Zivilisation oder eines Individuums mit dem Symbiosenetzwerk, deckt mehrere Dimensionen wie Grad der Ressourcenteilisung, Kooperationshäufigkeit und Anteil altruistischen Verhaltens ab.</td></tr><tr><td>37</td><td>Anker-Rat</td><td>Das höchste Machtorgan der Anker-Symbiose-Zivilisation, besteht aus Vertretern aller Rassen nach Verhältnis, übt Gesetzgebungsgewalt und Entscheidungsgewalt über wichtige Angelegenheiten aus.</td></tr><tr><td>38</td><td>Symbiose-Exekutivausschuss</td><td>Das höchste Verwaltungsorgan der Anker-Symbiose-Zivilisation, ist für die Durchführung der Verfassung und der Gesetze sowie die tägliche Governance verantwortlich.</td></tr><tr><td>39</td><td>Symbiose-Gericht</td><td>Das höchste Justizorgan der Anker-Symbiose-Zivilisation, übt unabhängig die Gerichtsbarkeit aus, ist für die Verfassungsmäßigkeitsprüfung und die Verhandlung wichtiger Fälle verantwortlich.</td></tr><tr><td>40</td><td>Dimensionsverwaltungsbüro</td><td>Eine spezielle Einrichtung unter dem Anker-Rat, ist für die Wartung der Gesamtkoordinatenbank der Dimensionen, die Genehmigung von Traversierungslizenzen, die Verwaltung der interdimensionalen Archäologie und andere Angelegenheiten verantwortlich.</td></tr></tbody></table><h2 id="_3-normen-fur-die-verwendung-von-begriffen" tabindex="-1">3. Normen für die Verwendung von Begriffen <a class="header-anchor" href="#_3-normen-fur-die-verwendung-von-begriffen" aria-label="Permalink to &quot;3. Normen für die Verwendung von Begriffen&quot;">​</a></h2><ol><li>Die in diesem Glossar gesammelten Begriffe sind Standardbegriffe, und alle Dokumente sollten der Verwendung der Standardausdrücke in diesem Glossar Vorrang geben.</li><li>Dasselbe Konzept muss in verschiedenen Dokumenten denselben Begriff verwenden, und Synonyme dürfen nicht willkürlich ausgetauscht werden.</li><li>Neue Begriffe, die in neuen Einstellungen entstehen, müssen rechtzeitig dem Begriffsausschuss zur Prüfung vorgelegt werden, und nach bestandener Prüfung werden sie diesem Glossar hinzugefügt.</li><li>Wenn die Definition eines Begriffs überarbeitet wird, gilt die neueste Version dieses Glossars als Maßstab, und gleichzeitig muss der Überarbeitungsinhalt in der Versionserklärung des Dokuments aufgezeichnet werden.</li><li>Bei der Zitierung eines Begriffs kann bei der ersten Erwähnung der vollständige Name verwendet werden, und anschließend kann die Abkürzung verwendet werden, aber es muss sichergestellt werden, dass die Bedeutung im Kontext klar ist.</li></ol><h2 id="schlussfolgerung" tabindex="-1">Schlussfolgerung <a class="header-anchor" href="#schlussfolgerung" aria-label="Permalink to &quot;Schlussfolgerung&quot;">​</a></h2><p>Das Begriffsglossar ist der sprachliche Grundstein des gesamten Einstellungssystems. Das vereinheitlichte Begriffssystem gewährleistet die Konzeptkonsistenz zwischen hundert Dokumenten und ermöglicht es den Lesern, nahtlos zwischen verschiedenen Modulen zu wechseln, ohne dass es zu Verständnisambiguitäten kommt. Mit der kontinuierlichen Bereicherung und Verbesserung des Einstellungssystems wird dieses Glossar kontinuierlich aktualisiert und dient stets als maßgebliche Quelle der Begriffe für alle Dokumente.</p><h2 id="verwandte-dokumente" tabindex="-1">Verwandte Dokumente <a class="header-anchor" href="#verwandte-dokumente" aria-label="Permalink to &quot;Verwandte Dokumente&quot;">​</a></h2><ul><li>00-Übersicht über das Universum Hengyuanzhou</li><li>02-Definition und Wesen des Anker-Ursprungs</li><li>99-Versions- und Wartungserklärung der Dokumente</li></ul>',12)])])}const m=n(s,[["render",d]]);export{c as __pageData,m as default};
